/**
 * dsh-team-dev bundled-skill provider and the zero-dependency
 * `createUserMessage` factory the generated guard consumes.
 * Hand-written fixed part — NOT generated by scripts/sync.mjs.
 */
import { readFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'

const BUNDLED_SKILL_RANK = 600
const PROVIDER_NAME = 'dsh-team-dev'

/** Replicate the host's `createUserMessage` factory shape without importing it. */
export function createUserMessage(input) {
  return Object.freeze({ role: 'user', id: globalThis.crypto.randomUUID(), content: input.content, source: input.source })
}

/** Parse the single-line `name` / `description` frontmatter fields of a SKILL.md body. */
function parseFrontmatter(text) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(text)
  if (!match) return {}
  const out = {}
  for (const line of match[1].split(/\r?\n/)) {
    const index = line.indexOf(':')
    if (index > 0) out[line.slice(0, index).trim()] = line.slice(index + 1).trim()
  }
  return out
}

const SKILL_NAMES = ['team-dev', 'team-boot']
const SKILLS = SKILL_NAMES.map(skillName => {
  const directory = new URL(`../skills/${skillName}/`, import.meta.url)
  const locator = new URL(`../skills/${skillName}/SKILL.md`, import.meta.url)
  return {
    name: skillName,
    directory,
    locator,
    resourceBase: { kind: 'directory', path: fileURLToPath(directory) },
  }
})

const provider = {
  name: PROVIDER_NAME,
  async list() {
    const candidates = []
    for (const skill of SKILLS) {
      const body = await readFile(skill.locator, 'utf8')
      const meta = parseFrontmatter(body)
      const description = meta.description ?? ''
      if (!description) throw new Error(`dsh-team-dev: skill "${skill.name}" SKILL.md is missing a description`)
      candidates.push({
        name: skill.name,
        description,
        invocation: { modelInvocable: true, userInvocable: true },
        provider: PROVIDER_NAME,
        source: 'bundled',
        resourceBase: skill.resourceBase,
        rank: BUNDLED_SKILL_RANK,
        locator: skill.locator,
      })
    }
    return candidates
  },
  async get(candidate) {
    const body = await readFile(candidate.locator, 'utf8')
    const meta = parseFrontmatter(body)
    return {
      name: candidate.name,
      description: meta.description ?? candidate.description,
      invocation: candidate.invocation,
      provider: PROVIDER_NAME,
      source: 'bundled',
      resourceBase: candidate.resourceBase,
      content: body,
    }
  },
}

/** Register the bundled provider on `ctx.skills`. */
export function skillsApply(ctx) {
  ctx.skills.registerProvider(() => provider)
}
